import { useState } from 'react';
import { Link, useLocation } from 'react-router-dom';
import { Minus, Plus, Trash2, ArrowRight } from 'lucide-react';
import Navbar from '../components/Navbar';

interface CartItem {
  id: string;
  name: string;
  price: number;
  qty: number;
  image: string;
}

const sampleCart: CartItem[] = [
  { id: 'm4', name: 'Wagyu Ribeye', price: 89, qty: 1, image: 'https://images.pexels.com/photos/1639557/pexels-photo-1639557.jpeg?auto=compress&cs=tinysrgb&w=400' },
  { id: 'm1', name: 'Seared Scallops', price: 24, qty: 2, image: 'https://images.pexels.com/photos/3655916/pexels-photo-3655916.jpeg?auto=compress&cs=tinysrgb&w=400' },
  { id: 'm8', name: 'Valrhona Chocolate Fondant', price: 16, qty: 1, image: 'https://images.pexels.com/photos/291528/pexels-photo-291528.jpeg?auto=compress&cs=tinysrgb&w=400' },
];

const sizes = ['Small', 'Medium', 'Large'];

export default function CartPage() {
  const location = useLocation();
  const initialCart = (location.state as any)?.cart || sampleCart;
  const restaurantName = (location.state as any)?.restaurant || 'Ember & Oak';

  const [items, setItems] = useState<CartItem[]>(initialCart);
  const [itemSizes, setItemSizes] = useState<Record<string, string>>({});
  const [address, setAddress] = useState('');

  const updateQty = (id: string, delta: number) => {
    setItems(prev => prev.map(c => c.id === id ? { ...c, qty: Math.max(1, c.qty + delta) } : c));
  };

  const remove = (id: string) => {
    setItems(prev => prev.filter(c => c.id !== id));
  };

  const subtotal = items.reduce((s, c) => s + c.price * c.qty, 0);
  const delivery = 4.99;
  const total = subtotal + delivery;

  return (
    <div className="bg-warm-950 min-h-screen pt-[72px]">
      <Navbar />
      <div className="max-w-6xl mx-auto px-12 py-12">
        <div className="mb-8">
          <p className="text-amber text-xs font-medium tracking-[0.3em] uppercase mb-2">Your Order</p>
          <h1 className="font-display text-4xl text-cream">Cart</h1>
          <p className="text-cream-muted text-sm mt-1">Ordering from <span className="text-cream">{restaurantName}</span></p>
        </div>

        <div className="flex gap-10">
          {/* Items list */}
          <div className="flex-1 space-y-4">
            {items.length === 0 ? (
              <div className="bg-warm-800 rounded-2xl p-16 text-center border border-warm-700">
                <p className="text-cream-muted text-lg">Your cart is empty</p>
                <Link to="/discover" className="inline-block mt-4 text-amber hover:text-amber-light text-sm">Browse restaurants →</Link>
              </div>
            ) : items.map(item => {
              const size = itemSizes[item.id] || 'Medium';
              return (
                <div key={item.id} className="flex items-center gap-5 bg-warm-800 border border-warm-700 rounded-2xl p-5 hover:border-warm-600 transition-colors">
                  <img src={item.image} alt={item.name} className="w-20 h-20 rounded-xl object-cover flex-shrink-0" />
                  <div className="flex-1 min-w-0">
                    <h3 className="font-display text-base text-cream font-medium mb-2">{item.name}</h3>
                    {/* Size selector */}
                    <div className="flex gap-2 mb-1">
                      {sizes.map(s => (
                        <button
                          key={s}
                          onClick={() => setItemSizes(prev => ({ ...prev, [item.id]: s }))}
                          className={`px-3 py-1 rounded-lg text-xs font-medium transition-all ${
                            size === s ? 'bg-amber text-warm-950' : 'bg-warm-750 text-cream-muted hover:text-cream border border-warm-700'
                          }`}
                        >
                          {s}
                        </button>
                      ))}
                    </div>
                  </div>
                  {/* Qty control */}
                  <div className="flex items-center gap-2">
                    <button onClick={() => updateQty(item.id, -1)} className="w-8 h-8 flex items-center justify-center rounded-lg bg-warm-750 hover:bg-warm-700 text-cream transition-colors">
                      <Minus size={14} />
                    </button>
                    <span className="text-cream w-6 text-center font-medium">{item.qty}</span>
                    <button onClick={() => updateQty(item.id, 1)} className="w-8 h-8 flex items-center justify-center rounded-lg bg-warm-750 hover:bg-warm-700 text-cream transition-colors">
                      <Plus size={14} />
                    </button>
                  </div>
                  <div className="text-right min-w-[70px]">
                    <p className="text-amber font-semibold">${(item.price * item.qty).toFixed(2)}</p>
                    <p className="text-warm-500 text-xs">${item.price} each</p>
                  </div>
                  <button onClick={() => remove(item.id)} className="text-warm-500 hover:text-red-400 transition-colors p-1">
                    <Trash2 size={16} />
                  </button>
                </div>
              );
            })}

            {/* Address */}
            <div className="bg-warm-800 border border-warm-700 rounded-2xl p-6 mt-6">
              <h3 className="font-display text-lg text-cream mb-4">Delivery Address</h3>
              <input
                type="text"
                value={address}
                onChange={e => setAddress(e.target.value)}
                placeholder="Enter your full delivery address..."
                className="w-full bg-warm-750 border border-warm-700 rounded-xl px-4 py-3 text-cream placeholder-warm-500 focus:outline-none focus:border-amber transition-colors text-sm"
              />
            </div>
          </div>

          {/* Order Summary */}
          <div className="w-80 flex-shrink-0">
            <div className="bg-warm-900 border border-warm-700 rounded-2xl p-6 sticky top-24">
              <h3 className="font-display text-xl text-cream mb-6">Order Summary</h3>
              <div className="space-y-3 mb-6">
                {items.map(item => (
                  <div key={item.id} className="flex justify-between text-sm">
                    <span className="text-cream-muted">{item.name} ×{item.qty}</span>
                    <span className="text-cream">${(item.price * item.qty).toFixed(2)}</span>
                  </div>
                ))}
              </div>
              <div className="border-t border-warm-700 pt-4 space-y-2 mb-6">
                <div className="flex justify-between text-sm">
                  <span className="text-cream-muted">Subtotal</span>
                  <span className="text-cream">${subtotal.toFixed(2)}</span>
                </div>
                <div className="flex justify-between text-sm">
                  <span className="text-cream-muted">Delivery fee</span>
                  <span className="text-cream">${delivery.toFixed(2)}</span>
                </div>
              </div>
              <div className="flex justify-between items-center mb-6">
                <span className="text-cream font-semibold">Total</span>
                <span className="text-amber text-2xl font-semibold font-display">${total.toFixed(2)}</span>
              </div>
              <Link
                to="/order-tracking"
                className="flex items-center justify-center gap-2 w-full py-3.5 bg-amber hover:bg-amber-hover text-warm-950 font-semibold rounded-xl transition-colors duration-200"
              >
                Place Order
                <ArrowRight size={16} />
              </Link>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

src/pages/DiscoverPage.tsx:
import { useState } from 'react';
import { Link } from 'react-router-dom';
import { Search, MapPin, Star, ChevronDown } from 'lucide-react';
import Navbar from '../components/Navbar';
import { restaurants } from '../data/dummyData';

const cuisines = ['All', 'American', 'Indian', 'French', 'Japanese', 'Italian', 'Mediterranean'];
const ratings = ['Any', '4.5+', '4.7+', '4.9+'];

export default function DiscoverPage() {
  const [activeCuisine, setActiveCuisine] = useState('All');
  const [activeRating, setActiveRating] = useState('Any');
  const [search, setSearch] = useState('');

  const filtered = restaurants.filter(r => {
    const matchCuisine = activeCuisine === 'All' || r.cuisine.includes(activeCuisine);
    const matchRating =
      activeRating === 'Any' ? true :
      activeRating === '4.5+' ? r.rating >= 4.5 :
      activeRating === '4.7+' ? r.rating >= 4.7 :
      r.rating >= 4.9;
    const matchSearch = r.name.toLowerCase().includes(search.toLowerCase()) ||
      r.cuisine.toLowerCase().includes(search.toLowerCase());
    return matchCuisine && matchRating && matchSearch;
  });

  return (
    <div className="bg-warm-950 min-h-screen pt-20">
      <Navbar />

      {/* Search header */}
      <div className="bg-warm-900 border-b border-warm-700 px-16 py-8">
        <div className="max-w-7xl mx-auto">
          <h1 className="font-display text-3xl text-cream mb-6">Discover Near You</h1>
          <div className="flex items-center gap-3">
            <div className="flex-1 relative">
              <Search size={18} className="absolute left-4 top-1/2 -translate-y-1/2 text-warm-500" />
              <input
                type="text"
                value={search}
                onChange={e => setSearch(e.target.value)}
                placeholder="Search restaurants, cuisines..."
                className="w-full bg-warm-800 border border-warm-700 rounded-xl pl-11 pr-4 py-3.5 text-cream placeholder-warm-500 focus:outline-none focus:border-amber transition-colors text-sm"
              />
            </div>
            <button className="flex items-center gap-2 px-4 py-3.5 bg-warm-800 border border-warm-700 rounded-xl text-cream-muted hover:text-cream hover:border-warm-600 transition-all text-sm">
              <MapPin size={16} className="text-amber" />
              Downtown
              <ChevronDown size={14} />
            </button>
          </div>
        </div>
      </div>

      {/* Filters */}
      <div className="max-w-7xl mx-auto px-16 py-6">
        <div className="flex items-center gap-6 flex-wrap">
          <div className="flex items-center gap-2">
            <span className="text-cream-muted text-xs uppercase tracking-widest font-medium">Cuisine</span>
            <div className="flex gap-2 flex-wrap">
              {cuisines.map(c => (
                <button
                  key={c}
                  onClick={() => setActiveCuisine(c)}
                  className={`px-4 py-1.5 rounded-full text-xs font-medium transition-all duration-200 ${
                    activeCuisine === c
                      ? 'bg-amber text-warm-950'
                      : 'bg-warm-800 text-cream-muted hover:text-cream border border-warm-700 hover:border-warm-600'
                  }`}
                >
                  {c}
                </button>
              ))}
            </div>
          </div>
          <div className="w-px h-4 bg-warm-700" />
          <div className="flex items-center gap-2">
            <span className="text-cream-muted text-xs uppercase tracking-widest font-medium">Rating</span>
            <div className="flex gap-2">
              {ratings.map(r => (
                <button
                  key={r}
                  onClick={() => setActiveRating(r)}
                  className={`px-4 py-1.5 rounded-full text-xs font-medium transition-all duration-200 ${
                    activeRating === r
                      ? 'bg-amber text-warm-950'
                      : 'bg-warm-800 text-cream-muted hover:text-cream border border-warm-700 hover:border-warm-600'
                  }`}
                >
                  {r}
                </button>
              ))}
            </div>
          </div>
        </div>
      </div>

      {/* Restaurant Grid */}
      <div className="max-w-7xl mx-auto px-16 pb-16">
        <p className="text-cream-muted text-sm mb-6">{filtered.length} restaurants found</p>
        <div className="grid grid-cols-3 gap-7">
          {filtered.map(r => (
            <Link
              key={r.id}
              to={`/restaurant/${r.id}`}
              className="group bg-warm-800 border border-warm-700 rounded-2xl overflow-hidden hover:border-amber/40 transition-all duration-300 hover:-translate-y-1 hover:shadow-2xl hover:shadow-amber/10"
            >
              <div className="relative aspect-[16/10] overflow-hidden">
                <img
                  src={r.image}
                  alt={r.name}
                  className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500"
                />
                <div className="absolute top-3 right-3">
                  <span className={`px-2.5 py-1 rounded-full text-xs font-semibold ${
                    r.isOpen ? 'bg-green-900/80 text-green-300' : 'bg-warm-950/80 text-warm-500'
                  }`}>
                    {r.isOpen ? 'Open Now' : 'Closed'}
                  </span>
                </div>
              </div>
              <div className="p-5">
                <div className="flex items-start justify-between mb-1">
                  <h3 className="font-display text-lg text-cream font-medium group-hover:text-amber transition-colors">{r.name}</h3>
                  <span className="text-cream-muted text-sm ml-2 flex-shrink-0">{r.priceRange}</span>
                </div>
                <p className="text-cream-muted text-sm mb-3">{r.cuisine}</p>
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-1">
                    {[...Array(5)].map((_, i) => (
                      <Star
                        key={i}
                        size={13}
                        className={i < Math.floor(r.rating) ? 'text-amber fill-amber' : 'text-warm-600'}
                      />
                    ))}
                    <span className="text-amber text-sm font-semibold ml-1">{r.rating}</span>
                    <span className="text-warm-500 text-xs ml-1">({r.reviewCount})</span>
                  </div>
                  <div className="flex items-center gap-1 text-cream-muted text-xs">
                    <MapPin size={12} className="text-amber" />
                    {r.distance}
                  </div>
                </div>
              </div>
            </Link>
          ))}
        </div>
      </div>
    </div>
  );
}

